func GenerateFromField(f reflect.StructField, mode Mode, definedRefs map[string]NestedSchemaReference) (string, bool, *Schema, error) { // nolint gocyclo
	jsonTags := strings.Split(f.Tag.Get("json"), ",")
	name := strings.ToLower(f.Name)

	if len(jsonTags) > 0 && jsonTags[0] != "" {
		name = jsonTags[0]
	}

	if name == "-" || !f.IsExported() {
		// Skip deliberately filtered out items
		return name, false, nil, nil
	}

	s, err := GenerateWithMode(f.Type, mode, nil, definedRefs)
	if err != nil {
		return name, false, nil, err
	}

	for _, tag := range []string{"description", "doc", "format", "enum", "default", "example", "minimum", "exclusiveMinimum", "maximum", "exclusiveMaximum", "multipleOf", "minLength", "maxLength", "pattern", "minItems", "maxItems", "uniqueItems", "minProperties", "maxProperties", "nullable", "readOnly", "writeOnly", "deprecated"} {
		if tagValue, ok := f.Tag.Lookup(tag); ok {
			switch tag {
			case "description", "doc":
				s.Description = tagValue
			case "format":
				s.Format = tagValue
			case "enum":
				if err := handleEnumTag(f, s, tagValue); err != nil {
					return name, false, nil, err
				}
			case "default":
				if v, err := getTagValue(s, f.Type, tagValue); err == nil {
					s.Default = v
				} else {
					return name, false, nil, err
				}
			case "example":
				if v, err := getTagValue(s, f.Type, tagValue); err == nil {
					s.Example = v
				} else {
					return name, false, nil, err
				}
			case "minimum":
				if min, err := strconv.ParseFloat(tagValue, 64); err == nil {
					s.Minimum = &min
				} else {
					return name, false, nil, err
				}
			case "exclusiveMinimum":
				if min, err := strconv.ParseFloat(tagValue, 64); err == nil {
					s.Minimum = &min
					t := true
					s.ExclusiveMinimum = &t
				} else {
					return name, false, nil, err
				}
			case "maximum":
				if max, err := strconv.ParseFloat(tagValue, 64); err == nil {
					s.Maximum = &max
				} else {
					return name, false, nil, err
				}
			case "exclusiveMaximum":
				if max, err := strconv.ParseFloat(tagValue, 64); err == nil {
					s.Maximum = &max
					t := true
					s.ExclusiveMaximum = &t
				} else {
					return name, false, nil, err
				}
			case "multipleOf":
				if mof, err := strconv.ParseFloat(tagValue, 64); err == nil {
					s.MultipleOf = mof
				} else {
					return name, false, nil, err
				}
			case "minLength":
				if min, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MinLength = &min
				} else {
					return name, false, nil, err
				}
			case "maxLength":
				if max, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MaxLength = &max
				} else {
					return name, false, nil, err
				}
			case "pattern":
				s.Pattern = tagValue
				if _, err := regexp.Compile(s.Pattern); err != nil {
					return name, false, nil, err
				}
			case "minItems":
				if min, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MinItems = &min
				} else {
					return name, false, nil, err
				}
			case "maxItems":
				if max, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MaxItems = &max
				} else {
					return name, false, nil, err
				}
			case "uniqueItems":
				if tagValue == "true" {
					s.UniqueItems = true
				} else if tagValue == "false" {
					s.UniqueItems = false
				} else {
					return name, false, nil, fmt.Errorf("%s uniqueItems: boolean should be true or false: %w", f.Name, ErrSchemaInvalid)
				}
			case "minProperties":
				if min, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MinProperties = &min
				} else {
					return name, false, nil, err
				}
			case "maxProperties":
				if max, err := strconv.ParseUint(tagValue, 10, 64); err == nil {
					s.MaxProperties = &max
				} else {
					return name, false, nil, err
				}
			case "nullable":
				if tagValue == "true" {
					s.Nullable = true
				} else if tagValue == "false" {
					s.Nullable = false
				} else {
					return name, false, nil, fmt.Errorf("%s nullable: boolean should be true or false but got %s: %w", f.Name, tagValue, ErrSchemaInvalid)
				}
			case "readOnly":
				if tagValue == "true" {
					s.ReadOnly = true
				} else if tagValue == "false" {
					s.ReadOnly = false
				} else {
					return name, false, nil, fmt.Errorf("%s readOnly: boolean should be true or false: %w", f.Name, ErrSchemaInvalid)
				}
			case "writeOnly":
				if tagValue == "true" {
					s.WriteOnly = true
				} else if tagValue == "false" {
					s.WriteOnly = false
				} else {
					return name, false, nil, fmt.Errorf("%s writeOnly: boolean should be true or false: %w", f.Name, ErrSchemaInvalid)
				}
			case "deprecated":
				if tagValue == "true" {
					s.Deprecated = true
				} else if tagValue == "false" {
					s.Deprecated = false
				} else {
					return name, false, nil, fmt.Errorf("%s deprecated: boolean should be true or false: %w", f.Name, ErrSchemaInvalid)
				}
			}
		}
	}

	optional := false

	for _, tag := range jsonTags[1:] {
		if tag == "omitempty" {
			optional = true
		}
	}

	return name, optional, s, nil
}

func GenerateWithMode(t reflect.Type, mode Mode, schema *Schema, definedRefs map[string]NestedSchemaReference) (*Schema, error) { // nolint gocyclo
	if schema == nil {
		schema = &Schema{}
	}

	if t == ipType {
		// Special case: IP address.
		return &Schema{Type: TypeString, Format: "ipv4"}, nil
	}

	switch t.Kind() { // nolint exhaustive
	case reflect.Struct:
		// Handle special cases.
		switch t {
		case timeType:
			return &Schema{Type: TypeString, Format: "date-time"}, nil
		case uriType:
			return &Schema{Type: TypeString, Format: "uri"}, nil
		}

		if !GenerateInline {
			tname := t.Name()
			if tname != "" {
				ref, exists := definedRefs[tname]
				if exists {
					return &Schema{Ref: ref.Ref}, nil
				}

				definedRefs[tname] = NestedSchemaReference{
					Name: tname,
					Ref:  fmt.Sprintf("#/components/schemas/%s", tname),
					Type: t,
				}
			}
		}

		properties := make(map[string]*Schema)
		required := make([]string, 0)
		schema.Type = TypeObject
		schema.AdditionalProperties = false

		for _, f := range getFields(t) {
			name, optional, s, err := GenerateFromField(f, mode, definedRefs)
			if err != nil {
				return nil, err
			}

			if s == nil {
				// Skip deliberately filtered out items
				continue
			}

			if _, ok := properties[name]; ok {
				// Item already exists, ignore it since we process embedded fields
				// after top-level ones.
				continue
			}

			if s.ReadOnly && mode == ModeWrite {
				continue
			}

			if s.WriteOnly && mode == ModeRead {
				continue
			}

			properties[name] = s

			if !optional {
				required = append(required, name)
			}
		}

		if len(properties) > 0 {
			schema.Properties = properties
		}

		if len(required) > 0 {
			schema.Required = required
		}

	case reflect.Map:
		schema.Type = TypeObject

		s, err := GenerateWithMode(t.Elem(), mode, nil, definedRefs)
		if err != nil {
			return nil, err
		}

		schema.AdditionalProperties = s
	case reflect.Slice, reflect.Array:
		if t.Elem().Kind() == reflect.Uint8 {
			schema.Type = TypeString
		} else {
			schema.Type = TypeArray

			s, err := GenerateWithMode(t.Elem(), mode, nil, definedRefs)
			if err != nil {
				return nil, err
			}

			schema.Items = s
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32:
		schema.Type = TypeInteger
		schema.Format = "int32"
	case reflect.Int64:
		schema.Type = TypeInteger
		schema.Format = "int64"
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32:
		schema.Type = TypeInteger
		schema.Format = "int32"
		schema.Minimum = ptr(0.0) // Unsigned integers can't be negative.
	case reflect.Uint64:
		schema.Type = TypeInteger
		schema.Format = "int64"
		schema.Minimum = ptr(0.0) // Unsigned integers can't be negative.
	case reflect.Float32:
		schema.Type = TypeNumber
		schema.Format = "float"
	case reflect.Float64:
		schema.Type = TypeNumber
		schema.Format = "double"
	case reflect.Bool:
		schema.Type = TypeBoolean
	case reflect.String:
		schema.Type = TypeString
	case reflect.Ptr:
		return GenerateWithMode(t.Elem(), mode, schema, definedRefs)
	case reflect.Interface:
		// Interfaces can be any type.
	case reflect.Uintptr, reflect.UnsafePointer, reflect.Func:
		// Ignored...
	default:
		return nil, fmt.Errorf("unsupported type %s from %s", t.Kind(), t)
	}

	return schema, nil
}

func (cm *OpenAI) Generate(ctx context.Context, messages schema.ChatMessages, optFns ...func(o *schema.GenerateOptions)) (*schema.ModelResult, error) {
	opts := schema.GenerateOptions{
		CallbackManger: &callback.NoopManager{},
	}

	for _, fn := range optFns {
		fn(&opts)
	}

	openAIMessages, err := integration.ToOpenAIChatCompletionMessages(messages)
	if err != nil {
		return nil, err
	}

	var tools []openai.Tool
	if opts.Functions != nil {
		tools = util.Map(opts.Functions, func(fd schema.FunctionDefinition, i int) openai.Tool {
			return openai.Tool{
				Type: openai.ToolTypeFunction,
				Function: &openai.FunctionDefinition{
					Name:        fd.Name,
					Description: fd.Description,
					Parameters:  fd.Parameters,
				}}
		})
	}

	request := openai.ChatCompletionRequest{
		Model:            cm.opts.ModelName,
		Temperature:      cm.opts.Temperature,
		MaxTokens:        cm.opts.MaxTokens,
		TopP:             cm.opts.TopP,
		N:                cm.opts.N,
		PresencePenalty:  cm.opts.PresencePenalty,
		FrequencyPenalty: cm.opts.PresencePenalty,
		Messages:         openAIMessages,
		Tools:            tools,
		Stop:             opts.Stop,
	}

	if opts.ForceFunctionCall && len(opts.Functions) == 1 {
		request.ToolChoice = openai.ToolChoice{Type: openai.ToolTypeFunction, Function: openai.ToolFunction{
			Name: opts.Functions[0].Name,
		}}
	}

	choices := []openai.ChatCompletionChoice{}
	tokenUsage := make(map[string]int)

	if cm.opts.Stream {
		request.Stream = true

		stream, err := cm.client.CreateChatCompletionStream(ctx, request)
		if err != nil {
			return nil, err
		}

		defer stream.Close()

		var (
			role         string
			tokens       []string
			functionCall *openai.FunctionCall
			finishReason openai.FinishReason
		)

	streamProcessing:
		for {
			select {
			case <-ctx.Done():
				return nil, ctx.Err()
			default:
				res, err := stream.Recv()
				if errors.Is(err, io.EOF) {
					break streamProcessing
				}

				if err != nil {
					return nil, err
				}

				if err := opts.CallbackManger.OnModelNewToken(ctx, &schema.ModelNewTokenManagerInput{
					Token: res.Choices[0].Delta.Content,
				}); err != nil {
					return nil, err
				}

				role = res.Choices[0].Delta.Role
				tokens = append(tokens, res.Choices[0].Delta.Content)
				finishReason = res.Choices[0].FinishReason

				if len(res.Choices[0].Delta.ToolCalls) > 0 {
					functionCall = &res.Choices[0].Delta.ToolCalls[0].Function
				}
			}
		}

		choices = append(choices, openai.ChatCompletionChoice{
			Message: openai.ChatCompletionMessage{
				Role:         role,
				Content:      strings.Join(tokens, ""),
				FunctionCall: functionCall,
			},
			FinishReason: finishReason,
		})
	} else {
		res, err := cm.createChatCompletionWithRetry(ctx, request)
		if err != nil {
			return nil, err
		}

		choices = res.Choices

		tokenUsage["CompletionTokens"] += res.Usage.CompletionTokens
		tokenUsage["PromptTokens"] += res.Usage.PromptTokens
		tokenUsage["TotalTokens"] += res.Usage.TotalTokens
	}

	generations := util.Map(choices, func(choice openai.ChatCompletionChoice, _ int) schema.Generation {
		return schema.Generation{
			Text:    choice.Message.Content,
			Message: openAIResponseToChatMessage(choice.Message),
			Info: map[string]any{
				"FinishReason": string(choice.FinishReason),
			},
		}
	})

	return &schema.ModelResult{
		Generations: generations,
		LLMOutput: map[string]any{
			"ModelName":  cm.opts.ModelName,
			"TokenUsage": tokenUsage,
		},
	}, nil
}
